package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoPreciseTrimReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun trimActivity():HonorableVideoEditorActivity=activity().also{a->val p=VideoEditProject(20000);p.restore(listOf(VideoSegment(1000,10000,speed=2f,title="Trim",captions=listOf(VideoCaption(1100,1500,"Removed"),VideoCaption(3000,3500,"Kept"),VideoCaption(7500,9000,"Crossing")),captionSourceUri="content://synthetic/subtitles",motion=VideoMotion(true,endZoom=1.4f,anchorStartMs=1000,anchorEndMs=10000)),VideoSegment(12000,16000,title="Neighbor")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(a,"project",p);set(a,"primaryDurationMs",20000L);set(a,"durationMs",20000)}
 private fun editor(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"preciseTrimEditor",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,range:VideoTrimRange=VideoTrimRange(2000,8000)):Boolean {val p=get(a,"project")as VideoEditProject;return call(a,"commitPreciseTrimReview",d,r,p,0,p.segments[0],range)as Boolean}
 @Test fun currentTrimPreservesSettingsAnchorsMusicProvenanceAndOneUndo(){val a=trimActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val d=editor(a);val r=capture(a);assertTrue(commit(a,d,r));assertEquals(old[0].copy(startMs=2000,endMs=8000,captions=old[0].captions.drop(1)),p.segments[0]);assertSame(old[1],p.segments[1]);assertSame(music,p.soundtrack);assertEquals(7000L,p.totalDurationMs);assertNull(get(a,"preciseTrimEditor"));assertTrue(p.captionSourceUris().contains("content://synthetic/subtitles"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(2000L,p.segments[0].startMs)}
 @Test fun untrackedDismissedOrReplacedEditorCannotApply(){for(flag in listOf("untracked","dismissed","replaced")){val a=trimActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"dismissed"->showing(d,false);else->set(a,"preciseTrimEditor",dialog())};assertFalse(flag,commit(a,d,r));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceDurationRangeMusicSessionAndRecoveryReject(){for(flag in listOf("pause","generation","source","duration","range","music","mode","recovery","busy")){val a=trimActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",20001L);"range"->set(a,"selectedClip",1);"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,commit(a,d,r));assertSame(old,p.segments);assertNull(get(a,"preciseTrimEditor"))}}
 @Test fun consumedApprovalCannotRepeatOrReviveThroughUndo(){val a=trimActivity();val p=get(a,"project")as VideoEditProject;val d=editor(a);val r=capture(a);assertTrue(commit(a,d,r));assertFalse(commit(a,d,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,d,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun oldEditorCannotConsumeNewOwner(){val a=trimActivity();val old=editor(a);val current=editor(a);val r=capture(a);assertFalse(commit(a,old,r));assertSame(current,get(a,"preciseTrimEditor"));assertTrue(commit(a,current,r))}
 @Test fun defensiveRangeValidationOrNoOpCannotChangeHistory(){for(range in listOf(VideoTrimRange(-1,8000),VideoTrimRange(2000,10001),VideoTrimRange(7000,7000),VideoTrimRange(1000,10000))){val a=trimActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);if(range==VideoTrimRange(1000,10000))assertFalse(commit(a,d,r,range))else try{commit(a,d,r,range);fail("Accepted $range")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(old,p.segments);assertFalse(p.canUndo);assertNull(get(a,"preciseTrimEditor"))}}
 @Test fun preciseRangeSurvivesDraftRecoveryWithSourceAnchorsAndMusic(){val a=trimActivity();val p=get(a,"project")as VideoEditProject;val d=editor(a);val r=capture(a);assertTrue(commit(a,d,r));val first=p.segments[0];val draft=VideoDraft(20000,p.segments,0,first.startMs,first.startMs,first.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),20000));assertEquals(draft,restored);assertEquals(7500L,restored.segments[0].captions[1].startMs);assertEquals(9000L,restored.segments[0].captions[1].endMs);assertEquals(10000L,restored.segments[0].motion.anchorEndMs);assertEquals("content://synthetic/subtitles",restored.segments[0].captionSourceUri)}
 @Test fun pausedPreciseEntryReturnsBeforeWidgets(){val a=trimActivity();set(a,"workspaceActive",false);call(a,"preciseTrim");assertNull(get(a,"preciseTrimEditor"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}
}
